#if UNITY_EDITOR
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

// Real native inputs and raycast clicks. Large-value formatting sample is an adapter.
public static class NumberAuctionPresentationValidation
{
    const string Base=".tools/number-auction-1006/ui",Native=".tools/number-auction-1006/native";
    public static string Output {get;private set;}
    public static bool Running {get;private set;}
    [Serializable] class Meta {public string folder,status,runtimeHash;}
    static Transform Root=>GameObject.Find("Canvas").transform;
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static string Hash(string file){using var h=SHA256.Create();return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(file))).Replace("-","").ToLowerInvariant();}
    static string Folder(string name){var p=Native+"/"+name+"-result.json";var m=JsonUtility.FromJson<Meta>(File.ReadAllText(p));Check(m.status=="PASS"&&m.runtimeHash==JsonUtility.FromJson<Meta>(File.ReadAllText("ForgeRuntime/runtime.json")).runtimeHash,"Incomplete/stale native "+name);File.Copy(p,Output+"/inputs/"+name+"-meta.json",true);return m.folder;}
    static ForgeSeatView Read(string name,string label){string p=Path.Combine(Folder(name),label+".json");File.Copy(p,Output+"/inputs/"+name+"-"+label+".json",true);File.AppendAllText(Output+"/input-hashes.tsv",name+"/"+label+"\t"+Hash(p)+"\n");return JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p));}
    static IEnumerator Frame(){yield return new WaitForSecondsRealtime(.2f);yield return new WaitForEndOfFrame();Canvas.ForceUpdateCanvases();}
    static void Clean(){foreach(var p in UnityEngine.Object.FindObjectsByType<ForgeBattlefieldCardPointer>(FindObjectsSortMode.None)){p.ResetHover();p.enabled=false;}}
    static void Click(Button button){Check(button!=null&&button.interactable,"Missing/disabled "+button?.name);var rect=(RectTransform)button.transform;foreach(float y in new[]{.5f,.25f,.75f})foreach(float x in new[]{.5f,.12f,.88f}){var local=new Vector2(Mathf.Lerp(rect.rect.xMin,rect.rect.xMax,x),Mathf.Lerp(rect.rect.yMin,rect.rect.yMax,y));var p=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(local)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(p,hits);if(hits.Count>0&&hits[0].gameObject.GetComponentInParent<Button>()==button){ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,p,ExecuteEvents.pointerClickHandler);return;}}throw new Exception("Ray blocked "+button.name);}
    static Rect Bounds(Transform t){var c=new Vector3[4];((RectTransform)t).GetWorldCorners(c);return Rect.MinMaxRect(c.Min(p=>p.x),c.Min(p=>p.y),c.Max(p=>p.x),c.Max(p=>p.y));}
    static void DockBounds(Transform dock){foreach(var b in dock.GetComponentsInChildren<Button>()){Check(!Bounds(b.transform).Overlaps(Bounds(Root.Find("CornerCluster/ControlRow/PhaseTrack"))),"Phase covered");Check(!Bounds(b.transform).Overlaps(Bounds(Root.Find("PriorityControlMode"))),"AUTO covered");}var value=dock.Find("NumericValue").GetComponent<Text>();Check(!value.resizeTextForBestFit&&value.preferredWidth<=value.rectTransform.rect.width,"Numeric text overflow/shrink");foreach(string n in new[]{"Decrease","Increase","ConfirmValue"})Check(!Bounds(value.transform).Overlaps(Bounds(dock.Find(n))),"Number overlaps "+n);}
    static IEnumerator Shot(string lang,string label){if(lang!="zh-CN")yield break;ScreenCapture.CaptureScreenshot(Output+"/"+label+".png");yield return Frame();}
    public static void Run(){Check(Application.isPlaying&&!Running,"Play required/already running");Running=true;Output=Base+"/"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffffffZ");Directory.CreateDirectory(Output+"/inputs");File.WriteAllText(Base+"/latest.txt",Output);File.WriteAllText(Output+"/result.txt","RUNNING");File.WriteAllText(Output+"/producer-hashes.tsv",string.Join("\n",new[]{"Assets/Scripts/Editor/NumberAuctionPresentationValidation.cs","Assets/Scripts/UI/ForgeBattlefieldController.LandChoices.cs","Assets/Scripts/UI/ForgeBattlefieldController.Notices.cs","Tools/ForgeBridge/NativePatches.json"}.Select(p=>p+"\t"+Hash(p)))+"\n");var runner=new GameObject("NumberAuctionValidation");runner.AddComponent<Host>().StartCoroutine(Guard(Exercise(),runner));}
    sealed class Host:MonoBehaviour{}
    static IEnumerator Guard(IEnumerator e,GameObject runner){Exception error=null;while(true){bool more=false;object current=null;try{more=e.MoveNext();if(more)current=e.Current;}catch(Exception ex){error=ex;break;}if(!more)break;if(current is IEnumerator nested){yield return GuardChild(nested,ex=>error=ex);if(error!=null)break;}else yield return current;}try{(e as IDisposable)?.Dispose();}catch(Exception ex){error??=ex;}File.WriteAllText(Output+"/result.txt",error==null?"PASS: native auction raise/refuse both seats, mandatory increments and bounded number, large 123 native range, stale/duplicate/nonacting guards, dock layout and font stability in zh-CN/en-US/ja-JP; Int32-max formatting adapter only, no network claim.":"FAIL\n"+error);Running=false;UnityEngine.Object.Destroy(runner);}
    static IEnumerator GuardChild(IEnumerator e,Action<Exception> fail){while(true){bool more=false;object current=null;try{more=e.MoveNext();if(more)current=e.Current;}catch(Exception ex){fail(ex);break;}if(!more)break;if(current is IEnumerator nested)yield return GuardChild(nested,fail);else yield return current;}}
    static IEnumerator Exercise(){var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>()??new GameObject("NumberAuctionBattlefield").AddComponent<ForgeBattlefieldController>();bool enabled=ui.enabled;ui.enabled=false;string locale=GamePreferences.Language;var module=EventSystem.current.currentInputModule;bool input=module!=null&&module.enabled;if(module!=null)module.enabled=false;var notices=UnityEngine.Object.FindObjectsByType<ForgeBattlefieldMigrationNotice>(FindObjectsSortMode.None);var flags=notices.Select(n=>n.enabled).ToArray();foreach(var n in notices)n.enabled=false;
        try{foreach(string lang in new[]{"zh-CN","en-US","ja-JP"}){
            int revision=GamePreferences.Revision;bool change=GamePreferences.Language!=lang;GamePreferences.SetLanguage(lang);float until=Time.realtimeSinceStartup+20;while((!GamePreferences.Ready||change&&revision==GamePreferences.Revision)&&Time.realtimeSinceStartup<until)yield return null;Check(GamePreferences.Ready,"Locale unavailable");yield return Frame();File.AppendAllText(Output+"/steps.log","requested="+lang+" loaded="+GamePreferences.Language+"\n");
            foreach(int actor in new[]{1,2})foreach(string action in new[]{"ok","cancel"}){
                var v=Read("auction-caster",actor==1?"bid-confirm-3":"bid-confirm-2-other");Check(v.request.seat==actor,"Wrong bid actor");int calls=0,last=-1;ui.Present(null,actor,false,null,null,"");ui.Present(v,actor,true,i=>{calls++;last=i;},null,"");yield return Frame();Clean();var panel=GameObject.Find("CardAbilityChoices");Check(panel!=null&&panel.transform.parent==Root,"Bid confirmation missing");if(actor==1){var toast=Root.Find("ResultToast/ResultText").GetComponent<Text>();Check(toast.text.Contains(lang=="zh-CN"?"将生命竞价提高至 5":lang=="ja-JP"?"ライフの入札額を5":"Raised the life bid to 5"),"Native bid notice not localized: "+toast.text);}var title=panel.transform.Find("ValueTitle").GetComponent<Text>();string expected=lang=="zh-CN"?"提高生命竞价？":lang=="ja-JP"?"ライフの入札額を増やしますか？":"Raise the life bid?";Check(title.text.StartsWith(expected),"Auction locale "+title.text);Check(title.preferredHeight<=title.rectTransform.rect.height&&!title.resizeTextForBestFit,"Bid text overflow/shrink");var fonts=panel.GetComponentsInChildren<Text>().Select(t=>t.fontSize).ToArray();ui.ViewBattlefield();yield return Frame();Check(panel.GetComponentInParent<CanvasGroup>().alpha==0,"Bid window not hidden");ui.RestoreBattlefieldWindows();yield return Frame();Check(calls==0&&fonts.SequenceEqual(panel.GetComponentsInChildren<Text>().Select(t=>t.fontSize)),"Bid restore font/submission");int index=ui.OptionIndex(action);Check(!ui.TrySubmitPresentedOption(index,v.request.requestId-1),"Stale bid accepted");yield return Shot(lang,"bid-seat-"+actor+"-"+action);Click(panel.transform.Find("ValueOption_"+index).GetComponent<Button>());Check(calls==1&&last==index&&!ui.TrySubmitPresentedOption(index,v.request.requestId),"Bid action/duplicate");ui.Present(v,actor,false,i=>calls++,null,"");yield return Frame();Check(panel.GetComponentsInChildren<Button>().All(b=>!b.interactable)&&!ui.TrySubmitPresentedOption(index,v.request.requestId),"Nonactor bid enabled");
            }
            foreach(var v in new[]{Read("auction-caster","bid-increment-1"),Read("auction-caster","bid-increment-2-other"),Read("bounded-number","bounded-number")}){
                int actor=v.request.seat,calls=0,last=-1;ui.Present(null,actor,false,null,null,"");ui.Present(v,actor,true,i=>{calls++;last=i;},null,"");yield return Frame();Clean();var dock=Root.Find("CornerCluster/ControlRow/CardAbilityChoices");Check(dock!=null&&dock.gameObject.activeInHierarchy&&ui.OptionIndex("cancel")<0,"Mandatory range invented cancel/absent");DockBounds(dock);Check(!dock.Find("Decrease").GetComponent<Button>().interactable,"Below mandatory minimum");string minimum=v.request.options[0].label;Check(dock.Find("NumericValue").GetComponent<Text>().text==minimum,"Minimum mismatch");for(int i=1;i<v.request.options.Length;i++)Click(dock.Find("Increase").GetComponent<Button>());Check(calls==0&&!dock.Find("Increase").GetComponent<Button>().interactable&&dock.Find("NumericValue").GetComponent<Text>().text==v.request.options.Last().label,"Enumeration boundary/draft");yield return Shot(lang,"mandatory-seat-"+actor+"-max-"+v.request.options.Last().label);Click(dock.Find("ConfirmValue").GetComponent<Button>());Check(calls==1&&last==ui.OptionIndex(v.request.options.Last().id)&&!ui.TrySubmitPresentedOption(last,v.request.requestId),"Exact mandatory ID/duplicate");ui.Present(v,actor,false,i=>calls++,null,"");yield return Frame();Check(dock.GetComponentsInChildren<Button>().All(b=>!b.interactable),"Viewer numeric enabled");
            }
            foreach(int number in new[]{0,120,123}){
                var v=Read("hellion-large","number-"+number);int calls=0,last=-1;ui.Present(null,1,false,null,null,"");ui.Present(v,1,true,i=>{calls++;last=i;},null,"");yield return Frame();Clean();var dock=Root.Find("CornerCluster/ControlRow/CardAbilityChoices");DockBounds(dock);Check(dock.Find("NumericValue").GetComponent<Text>().text==number.ToString(),"Native number mismatch");Check(dock.Find("Decrease").GetComponent<Button>().interactable==(number>0),"Native minimum enabled");int expected=ui.OptionIndex(number==0?"number-plus":number==120?"number-minus":"confirm-number");Check(!ui.TrySubmitPresentedOption(expected,v.request.requestId-1),"Stale native number accepted");yield return Shot(lang,"native-value-"+number);Click(dock.Find(number==0?"Increase":number==120?"Decrease":"ConfirmValue").GetComponent<Button>());Check(calls==1&&last==expected&&!ui.TrySubmitPresentedOption(expected,v.request.requestId),"Native number action/duplicate");ui.Present(v,1,false,i=>calls++,null,"");yield return Frame();Check(dock.GetComponentsInChildren<Button>().All(b=>!b.interactable),"Viewer range enabled");
            }
            // Format-only adapter: mutate no engine and submit no synthesized request.
            var large=Read("hellion-large","number-final");large.request.selectedValue=int.MaxValue;ui.Present(null,1,false,null,null,"");ui.Present(large,1,false,null,null,"");yield return Frame();Clean();var big=Root.Find("CornerCluster/ControlRow/CardAbilityChoices");DockBounds(big);Check(big.Find("NumericValue").GetComponent<Text>().text=="2147483647","Large format lost digits");yield return Shot(lang,"int32-max-format-adapter");File.AppendAllText(Output+"/steps.log","PASS native clicks/locale and explicit format adapter "+lang+"\n");
            ui.Present(Read("hellion-large","resolved"),1,false,null,null,"");yield return Frame();Check(GameObject.Find("CardAbilityChoices")==null,"Number retained after next priority");
        }}finally{ui.Present(null,1,false,null,null,"");ui.enabled=enabled;GamePreferences.SetLanguage(locale);if(module!=null)module.enabled=input;for(int i=0;i<notices.Length;i++)if(notices[i]!=null)notices[i].enabled=flags[i];}
    }
}
#endif
